<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Mail,Storage};
use Illuminate\Support\Str;
use App\Services\{Commerce,Support,Workflow};
class MarketController extends Controller {
 private function done(Request $r,string $message,$data=null){return $r->expectsJson()?response()->json(['message'=>$message,'data'=>$data]):back()->with('success',$message);}
 public function panel(Request $r,string $module='overview'){
  if($module==='products')return redirect('/seller/products');if($module==='account')return redirect('/profile#security');$u=auth()->user();$seller=$u->role==='seller';$admin=$u->role==='admin';$forms=[];$records=collect();$title=ucfirst($module);
  $form=function($label,$action,$fields)use(&$forms){$forms[]=compact('label','action','fields');};
  if($module==='addresses'&&$u->role==='buyer'){return view('address-book',['links'=>app(CommonController::class)->links(),'addresses'=>DB::table('addresses')->where('user_id',$u->id)->get()]);
   $records=DB::table('addresses')->where('user_id',$u->id)->get();
   $form('Save address','/tools/address',['id?','recipient','phone','street','barangay','city','province','postal_code','is_default:checkbox']);
   $form('Delete address','/tools/address/delete',['id:number']);
  }elseif($module==='wishlist'&&$u->role==='buyer'){
   $records=DB::table('wishlists as w')->join('products as p','p.id','=','w.product_id')->where('w.buyer_id',$u->id)->select('p.id','p.name','p.stock','p.active')->get();
   $form('Wishlist product','/tools/wishlist',['product_id:number','enabled:checkbox']);$form('Follow store','/tools/follow',['seller_id:number','enabled:checkbox']);
  }elseif($module==='vouchers'&&$u->role==='buyer'){
   $records=DB::table('vouchers')->where('active',1)->where('claimable',1)->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->get();$form('Claim voucher','/tools/claim',['voucher_id:number']);
  }elseif($module==='store'&&$seller){return view('store-settings',['links'=>app(CommonController::class)->links(),'store'=>DB::table('seller_businesses')->where('user_id',$u->id)->first(),'categories'=>DB::table('store_categories')->where('seller_id',$u->id)->get()]);
   $records=DB::table('seller_businesses')->where('user_id',$u->id)->get();
   $form('Store settings','/tools/store',['name','description:textarea?','vacation:checkbox','logo:file?','banner:file?']);
   $form('Save store category','/tools/category',['id?','name','parent_id:number?','visible:checkbox','position:number']);
   $form('Delete store category','/tools/category/delete',['id:number']);
   $form('Assign store categories (up to 3)','/tools/product-categories',['product_id:number','category_ids']);
  }elseif($module==='vouchers'&&$seller || $module==='platform'&&$admin){return view('voucher-manager',['links'=>app(CommonController::class)->links(),'vouchers'=>DB::table('vouchers')->where('seller_id',$admin?null:$u->id)->get()]);}elseif($module==='promotions'&&$seller){
   $records=DB::table('promotions')->where('seller_id',$u->id)->get();
   $form('Schedule sale or flash sale','/tools/promotion',['id?','product_id:number','type:select:sale,flash','price:number','quantity:number?','starts_at:datetime-local','ends_at:datetime-local']);
   $form('Bundle or Buy X Get Y','/tools/deal',['type:select:bundle,buy_x_get_y','product_ids','minimum_quantity:number','percent:number','gift_product_id:number?','gift_quantity:number','starts_at:datetime-local','ends_at:datetime-local']);$form('End promotion','/tools/promotion/end',['id:number']);

  }elseif($module==='products'&&$seller){
   $records=DB::table('products')->where('seller_id',$u->id)->whereNull('deleted_at')->get();
   $form('Create or update product','/tools/product',['id?','name','description:textarea','category_id:number','price:number','discount_percent:number','stock:number','weight:number','purchase_limit:number?','draft:checkbox','images:file[]?']);
   $form('Product action','/tools/product/action',['id:number','action:select:activate,deactivate,delete,duplicate']);
   $form('Save variant (options JSON: {"Size":"M","Color":"Red"})','/tools/variant',['id?','product_id:number','name','sku','options','price_adjustment:number','stock:number','image:file?']);
   $form('Delete variant','/tools/variant/delete',['id:number']);
  }elseif($module==='returns'&&in_array($u->role,['buyer','seller'])){
   $records=DB::table('return_requests')->where($seller?'seller_id':'buyer_id',$u->id)->get();
   if(!$seller){$form('Request return','/tools/return',['order_id:number','reason:select:Damaged,Wrong item,Not as described','description:textarea','photos:file[]']);$form('Escalate rejected return','/tools/return/escalate',['id:number']);}
   else{$form('Respond to request','/tools/return/respond',['id:number','decision:select:approved,rejected','reason:textarea']);$form('Confirm returned items received','/tools/return/received',['id:number']);$form('Confirm return-to-sender received','/tools/rts-received',['parcel_id:number']);}
  }elseif($module==='earnings'&&$seller){
   $title='Available earnings: PHP '.number_format(Commerce::available($u->id),2);$records=DB::table('payouts')->where('seller_id',$u->id)->get();$form('Request payout','/tools/payout',['amount:number','account']);
  }elseif($module==='ratings'&&in_array($u->role,['buyer','seller'])){
   $records=DB::table('item_reviews as r')->join('order_items as oi','oi.id','=','r.order_item_id')->join('users as b','b.id','=','r.buyer_id')->where($seller?'r.seller_id':'r.buyer_id',$u->id)->select('r.*','oi.name as product_name','b.name as buyer_name')->orderByDesc('r.id')->get();
   if($seller)$form('Reply to review','/tools/review/reply',['id:number','response:textarea']);
   else $form('Rate order item','/tools/review',['order_item_id:number','stars:number','comment:textarea?','photos:file[]?']);
  }elseif($module==='platform'&&$admin){$records=DB::table('vouchers')->whereNull('seller_id')->get();$form('Create platform/shipping voucher','/tools/platform-voucher',['code','type:select:percent,fixed,shipping','value:number','minimum_spend:number','cap:number?','starts_at:datetime-local','expires_at:datetime-local','usage_limit:number','per_buyer_limit:number','claimable:checkbox']);}
  elseif($module==='payments'&&$admin){
   $records=collect()->concat(DB::table('payments')->where('method','manual')->get()->map(fn($x)=>(object)(['record_type'=>'payment']+(array)$x)))->concat(DB::table('refunds')->get()->map(fn($x)=>(object)(['record_type'=>'refund']+(array)$x)))->concat(DB::table('payouts')->get()->map(fn($x)=>(object)(['record_type'=>'payout']+(array)$x)))->concat(DB::table('return_requests')->where('status','disputed')->get()->map(fn($x)=>(object)(['record_type'=>'dispute']+(array)$x)));$form('Confirm manual payment','/tools/payment',['payment_id:number','reference']);
   $form('Resolve disputed return','/tools/dispute',['id:number','decision:select:approved,rejected','reason:textarea']);$form('Record completed refund','/tools/refund',['order_id:number','reference']);$form('Mark payout paid','/tools/payout/paid',['id:number','reference']);
  }elseif($module==='account'){
   $records=DB::table('notifications')->where('user_id',$u->id)->orderByDesc('id')->limit(50)->get();
   $form('Change password','/tools/password',['current_password:password','password:password','password_confirmation:password']);
   $form('Request email/phone change','/tools/contact/request',['email:email?','phone?','password:password']);
   $form('Verify contact change','/tools/contact/verify',['otp']);$form('Mark notifications read','/tools/notifications/read',[]);
  }else abort(404);
  if($module==='ratings'&&in_array($u->role,['buyer','seller']))return view('reviews',['links'=>app(CommonController::class)->links(),'reviews'=>$records,'seller'=>$seller,'forms'=>$forms]);
  return view('tools',['links'=>app(CommonController::class)->links(),'title'=>$title,'forms'=>$forms,'records'=>$records]);
 }
 public function address(Request $r){
  $r->merge(['phone'=>\App\Services\Registration::normalizePhone((string)$r->phone)]);
  $v=$r->validate(['id'=>'nullable|integer','recipient'=>'required|string|max:150','phone'=>['required','regex:/^09[0-9]{9}$/'],'street'=>'required|string|max:200','barangay'=>'required|string|max:120','city'=>'required|string|max:120','province'=>'required|string|max:120','postal_code'=>['required','regex:/^[0-9]{4}$/'],'is_default'=>'nullable|boolean']);
  \App\Services\Geography::validate($v);DB::transaction(function()use($v){DB::table('users')->where('id',auth()->id())->lockForUpdate()->first();$id=$v['id']??null;unset($v['id']);
   if($id)abort_unless(DB::table('addresses')->where('id',$id)->where('user_id',auth()->id())->exists(),403);
   elseif(DB::table('addresses')->where('user_id',auth()->id())->count()>=10)Support::fail('address','You can save up to 10 addresses.');
   $v['is_default']=($v['is_default']??false)||DB::table('addresses')->where('user_id',auth()->id())->count()===0;
   if($v['is_default'])DB::table('addresses')->where('user_id',auth()->id())->update(['is_default'=>0]);
   if($id)DB::table('addresses')->where('id',$id)->update($v+['updated_at'=>now()]);else DB::table('addresses')->insert($v+['user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);
  });return $this->done($r,'Address saved.');
 }
 public function addressDelete(Request $r){$v=$r->validate(['id'=>'required|integer']);$a=DB::table('addresses')->where('id',$v['id'])->where('user_id',auth()->id())->first();abort_unless($a,404);if($a->is_default)Support::fail('address','Choose another default address first.');
  // Keep referenced legacy addresses to protect old orders without snapshots.
  if(DB::table('orders')->where('address_id',$a->id)->exists())Support::fail('address','This address belongs to order history. Keep it and add a new address instead.');
  DB::table('addresses')->where('id',$a->id)->delete();return $this->done($r,'Address deleted.');}
 public function wishlist(Request $r){return $this->toggle($r,'wishlists','product_id','products');}
 public function follow(Request $r){return $this->toggle($r,'store_follows','seller_id','seller_businesses','user_id');}
 private function toggle(Request $r,string $table,string $field,string $target,string $targetKey='id'){$v=$r->validate([$field=>"required|integer|exists:{$target},{$targetKey}",'enabled'=>'nullable|boolean']);$q=[$field=>$v[$field],'buyer_id'=>auth()->id()];if($r->boolean('enabled'))DB::table($table)->insertOrIgnore($q+['created_at'=>now(),'updated_at'=>now()]);else DB::table($table)->where($q)->delete();return $this->done($r,'Saved.');}
 public function claim(Request $r)
 {
  $v = $r->validate(['voucher_id' => 'required|integer']);
  $voucher = DB::table('vouchers')->find($v['voucher_id']);

  if (!$voucher) {
   Support::fail('voucher_id', 'This voucher no longer exists.');
  }
  if (!$voucher->active) {
   Support::fail('voucher_id', 'This voucher is currently inactive.');
  }
  if (!$voucher->claimable) {
   Support::fail('voucher_id', 'This voucher is not available for claiming.');
  }
  if ($voucher->expires_at && now()->gte($voucher->expires_at)) {
   Support::fail('voucher_id', 'This voucher has already expired.');
  }

  DB::table('voucher_claims')->insertOrIgnore([
   'buyer_id' => auth()->id(),
   'voucher_id' => $voucher->id,
   'created_at' => now(),
   'updated_at' => now(),
  ]);

  return $this->done($r, 'Voucher claimed.');
 }

 public function store(Request $r){$store=DB::table('seller_businesses')->where('user_id',auth()->id())->first();abort_unless($store,404);if(($r->has('name')&&trim((string)$r->name)!==$store->name)||($r->has('category')&&$r->category!==$store->category))Support::fail('name','Registered store name and main category cannot be changed.');$r->merge(['name'=>$store->name]);$name=$store->name;$v=$r->validate(['name'=>'required|string|min:3|max:30','description'=>'nullable|string|max:500','vacation'=>'nullable|boolean','logo'=>'nullable|file|mimes:jpg,jpeg,png|extensions:jpg,jpeg,png|max:5120','banner'=>'nullable|file|mimes:jpg,jpeg,png|extensions:jpg,jpeg,png|max:5120']);
  if(mb_strlen($name)<3)Support::fail('name','Enter at least 3 characters.');if(DB::table('seller_businesses')->whereRaw('LOWER(TRIM(name)) = ?',[mb_strtolower($name)])->where('user_id','!=',auth()->id())->exists())Support::fail('name','Store name is already in use.');
  $data=['name'=>$name,'name_normalized'=>mb_strtolower($name),'description'=>$v['description']??null,'vacation'=>$r->boolean('vacation'),'updated_at'=>now()];foreach(['logo','banner'] as $f)if($r->hasFile($f))$data[$f]=$r->file($f)->store('stores','public');DB::table('seller_businesses')->where('user_id',auth()->id())->update($data);return $this->done($r,'Store settings saved.');}
 public function category(Request $r){$v=$r->validate(['id'=>'nullable|integer','name'=>'required|string|max:50','parent_id'=>'nullable|integer','visible'=>'nullable|boolean','position'=>'nullable|integer|min:0']);$id=$v['id']??null;unset($v['id']);$v['name']=trim($v['name']);if(!$v['name'])Support::fail('name','Enter a category name.');$v['position']=$v['position']??0;$v['normalized_name']=mb_strtolower($v['name']);$v['visible']=$r->boolean('visible');
  if($id)abort_unless(DB::table('store_categories')->where('id',$id)->where('seller_id',auth()->id())->exists(),403);
  if(!empty($v['parent_id'])){$parent=DB::table('store_categories')->where('id',$v['parent_id'])->where('seller_id',auth()->id())->first();if(!$parent||$parent->parent_id||$parent->id==$id||($id&&DB::table('store_categories')->where('parent_id',$id)->exists()))Support::fail('parent_id','Only two category levels are allowed.');}
  if(DB::table('store_categories')->where('seller_id',auth()->id())->where('normalized_name',$v['normalized_name'])->when($id,fn($q)=>$q->where('id','!=',$id))->exists())Support::fail('name','Duplicate category name.');
  if($id)DB::table('store_categories')->where('id',$id)->update($v+['updated_at'=>now()]);else DB::table('store_categories')->insert($v+['seller_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);return $this->done($r,'Category saved.');}
 public function categoryDelete(Request $r){$id=$r->validate(['id'=>'required|integer'])['id'];abort_unless(DB::table('store_categories')->where('id',$id)->where('seller_id',auth()->id())->exists(),403);DB::transaction(function()use($id){$ids=DB::table('store_categories')->where('parent_id',$id)->pluck('id')->push($id);DB::table('product_store_categories')->whereIn('category_id',$ids)->delete();DB::table('store_categories')->whereIn('id',$ids)->delete();});return $this->done($r,'Category deleted; affected products are uncategorized.');}
 public function productCategories(Request $r){$v=$r->validate(['product_id'=>'required|integer','category_ids'=>'required|array|min:1|max:3','category_ids.*'=>'integer']);$ids=array_unique(array_filter(array_map('intval',$v['category_ids'])));if(count($ids)>3)Support::fail('category_ids','Choose at most 3 categories.');abort_unless(DB::table('products')->where('id',$v['product_id'])->where('seller_id',auth()->id())->exists(),403);abort_unless(DB::table('store_categories')->whereIn('id',$ids)->where('seller_id',auth()->id())->count()===count($ids),403);DB::transaction(function()use($v,$ids){DB::table('product_store_categories')->where('product_id',$v['product_id'])->delete();foreach($ids as $id)DB::table('product_store_categories')->insert(['product_id'=>$v['product_id'],'category_id'=>$id]);});return $this->done($r,'Categories saved.');}
 public function product(Request $r,?int $id=null){$id=$id??($r->integer('id')?:null);$p=$id?DB::table('products')->where('id',$id)->where('seller_id',auth()->id())->whereNull('deleted_at')->first():null;if($id)abort_unless($p,403);
  $v=$r->validate(['name'=>'required|string|min:5|max:120','description'=>'required|string|min:20|max:3000','category_id'=>'required|integer|exists:categories,id','price'=>'required|numeric|decimal:0,2|min:1|max:1000000','discount_percent'=>'required|numeric|between:0,99.99','stock'=>'required|integer|between:0,99999','weight'=>'required|numeric|gt:0|max:99999','draft'=>'nullable|boolean','purchase_limit'=>'nullable|integer|between:1,99999']);\App\Services\ProductCategories::validate($v['category_id']);$images=Support::photos($r,'images',$p?0:1,9);$old=json_decode($p->images??'[]',true);if(count($old)+count($images)>9)Support::fail('images','A product may have at most 9 images.');$v['images']=json_encode(array_merge($old,$images));$v['draft']=$r->boolean('draft');
  if(Support::money($v['price']*(1-$v['discount_percent']/100))<1)Support::fail('price','Effective sale price must be at least PHP 1.00.');
  if($p){DB::table('products')->where('id',$p->id)->update($v+['approved'=>0,'updated_at'=>now()]);Commerce::stockAlert('products',$p->id);}else Support::once($r,'create-product',fn()=>DB::table('products')->insertGetId($v+['seller_id'=>auth()->id(),'active'=>1,'approved'=>0,'created_at'=>now(),'updated_at'=>now()]));return $this->done($r,'Product saved; publishing requires admin approval.');}
 public function productAction(Request $r){$v=$r->validate(['id'=>'required|integer','action'=>'required|in:activate,deactivate,delete,duplicate']);$p=DB::table('products')->where('id',$v['id'])->where('seller_id',auth()->id())->whereNull('deleted_at')->first();abort_unless($p,403);
  if($v['action']==='delete'){$busy=DB::table('order_items as i')->join('orders as o','o.id','=','i.order_id')->where('i.product_id',$p->id)->whereNotIn('o.status',['COMPLETED','CANCELLED','REFUNDED','RETURN_RECEIVED'])->exists();if($busy)Support::fail('product','Unfinished orders prevent deletion.');DB::table('products')->where('id',$p->id)->update(['deleted_at'=>now(),'active'=>0]);}
  elseif($v['action']==='duplicate'){Support::once($r,'duplicate-product',function()use($p){$data=(array)$p;unset($data['id']);$data['name']=mb_substr($p->name,0,112).' (copy)';$data['draft']=1;$data['approved']=0;$data['created_at']=now();$data['updated_at']=now();return DB::table('products')->insertGetId($data);});}
  else DB::table('products')->where('id',$p->id)->update(['active'=>$v['action']==='activate','updated_at'=>now()]);return $this->done($r,'Product updated.');}
 public function variant(Request $r){$v=$r->validate(['id'=>'nullable|integer','product_id'=>'required|integer','name'=>'required|string|max:120','sku'=>'required|string|max:100','options'=>'required|json','price_adjustment'=>'required|numeric|decimal:0,2','stock'=>'required|integer|between:0,99999','image'=>'nullable|file|mimes:jpg,jpeg,png|extensions:jpg,jpeg,png|max:5120']);$id=$v['id']??null;unset($v['id'],$v['image']);$p=DB::table('products')->where('id',$v['product_id'])->where('seller_id',auth()->id())->first();abort_unless($p,403);if($id)abort_unless(DB::table('product_variations')->where('id',$id)->where('product_id',$p->id)->exists(),403);
  $options=json_decode($v['options'],true);if(!is_array($options)||count($options)<1||count($options)>2||array_is_list($options))Support::fail('options','Use one or two named variation types in a JSON object.');foreach($options as $k=>$value)if(!is_string($value)||!trim($value))Support::fail('options','Variation options cannot be empty.');ksort($options);$v['options']=json_encode($options);
  if($p->price+$v['price_adjustment']<1||$p->price+$v['price_adjustment']>1000000)Support::fail('price_adjustment','Variant effective price is outside the allowed range.');
  $existing=DB::table('product_variations')->where('product_id',$p->id)->whereNull('deleted_at')->when($id,fn($q)=>$q->where('id','!=',$id))->get();foreach($existing as $x){$o=json_decode($x->options??'{}',true);ksort($o);if($o&&array_keys($o)!==array_keys($options))Support::fail('options','Use the same variation types for every variant.');if($o===$options)Support::fail('options','Duplicate option combination.');}foreach($options as $k=>$value){$values=[$value];foreach($existing as $x){$o=json_decode($x->options??'{}',true);if(isset($o[$k]))$values[]=$o[$k];}if(count(array_unique($values))>20)Support::fail('options','At most 20 options per type.');}
  if(DB::table('product_variations')->where('sku',$v['sku'])->when($id,fn($q)=>$q->where('id','!=',$id))->exists())Support::fail('sku','SKU already exists.');if($r->hasFile('image'))$v['image']=$r->file('image')->store('variants','public');
  if($id)DB::table('product_variations')->where('id',$id)->update($v+['updated_at'=>now()]);else Support::once($r,'variant',fn()=>DB::table('product_variations')->insertGetId($v+['created_at'=>now(),'updated_at'=>now()]));return $this->done($r,'Variant saved.');}
 public function variantDelete(Request $r){$id=$r->validate(['id'=>'required|integer'])['id'];$v=DB::table('product_variations')->find($id);abort_unless($v&&DB::table('products')->where('id',$v->product_id)->where('seller_id',auth()->id())->exists(),403);if(DB::table('order_items as i')->join('orders as o','o.id','=','i.order_id')->where('i.variation_id',$id)->whereNotIn('o.status',['COMPLETED','CANCELLED','REFUNDED','RETURN_RECEIVED'])->exists())Support::fail('variant','Unfinished orders prevent deletion.');DB::table('product_variations')->where('id',$id)->update(['deleted_at'=>now()]);return $this->done($r,'Variant removed from new purchases.');}
 public function promotion(Request $r){$v=$r->validate(['id'=>'nullable|integer','product_id'=>'required|integer','type'=>'required|in:sale,flash','price'=>'required|numeric|decimal:0,2|min:1','quantity'=>'required_if:type,flash|nullable|integer|min:1','starts_at'=>'required|date','ends_at'=>'required|date|after:starts_at']);$id=$v['id']??null;unset($v['id']);DB::transaction(function()use($v,$id){$p=DB::table('products')->where('id',$v['product_id'])->where('seller_id',auth()->id())->lockForUpdate()->first();abort_unless($p,403);if($id)abort_unless(DB::table('promotions')->where('id',$id)->where('seller_id',auth()->id())->exists(),403);if($v['price']>=$p->price)Support::fail('price','Sale price must be lower than the regular price.');if($v['type']==='flash'&&$v['quantity']>$p->stock)Support::fail('quantity','Flash quantity exceeds stock.');if(DB::table('promotions')->where('product_id',$p->id)->where('type',$v['type'])->where('active',1)->where('starts_at','<',$v['ends_at'])->where('ends_at','>',$v['starts_at'])->when($id,fn($q)=>$q->where('id','!=',$id))->exists())Support::fail('starts_at','Promotion schedules overlap.');if($id)DB::table('promotions')->where('id',$id)->update($v+['updated_at'=>now()]);else DB::table('promotions')->insert($v+['seller_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);});return $this->done($r,'Promotion scheduled.');}
 public function promotionEnd(Request $r){$id=$r->validate(['id'=>'required|integer'])['id'];abort_unless(DB::table('promotions')->where('id',$id)->where('seller_id',auth()->id())->update(['active'=>0,'ends_at'=>now(),'updated_at'=>now()]),404);return $this->done($r,'Promotion ended.');}
 public function voucher(Request $r){$r->merge(['code'=>strtoupper(trim((string)$r->code))]);$v=$r->validate(['id'=>'nullable|integer','code'=>['required','regex:/^[A-Z0-9]{4,12}$/'],'type'=>auth()->user()->role==='admin'?'required|in:percent,fixed,shipping':'required|in:percent,fixed','value'=>'required|numeric|gt:0','minimum_spend'=>'required|numeric|min:0','cap'=>'nullable|numeric|gt:0','starts_at'=>'required|date','expires_at'=>'required|date|after:starts_at','usage_limit'=>'required|integer|min:1','per_buyer_limit'=>'required|integer|min:1','claimable'=>'nullable|boolean']);$id=$v['id']??null;unset($v['id']);if($v['type']==='percent'&&$v['value']>100)Support::fail('value','Percentage cannot exceed 100.');if(DB::table('vouchers')->where('code',$v['code'])->when($id,fn($q)=>$q->where('id','!=',$id))->exists())Support::fail('code','Voucher code is already used.');$v['claimable']=$r->boolean('claimable');$v['discount_percent']=$v['type']==='percent'?$v['value']:0;
  if($id){$old=DB::table('vouchers')->where('id',$id)->where('seller_id',auth()->user()->role==='admin'?null:auth()->id())->first();abort_unless($old,403);if(DB::table('voucher_claims')->where('voucher_id',$id)->exists()){$locked=array_diff_key($v,array_flip(['expires_at','usage_limit']));foreach($locked as $k=>$value)if((string)$value!==(string)$old->$k)Support::fail($k,'Claimed vouchers allow only end-date extensions and usage-limit increases.');if(now()->parse($v['expires_at'])->lt($old->expires_at)||$v['usage_limit']<$old->usage_limit)Support::fail('voucher','Only extensions and increases are allowed.');}DB::table('vouchers')->where('id',$id)->update($v+['updated_at'=>now()]);}
  else Support::once($r,'voucher',fn()=>DB::table('vouchers')->insertGetId($v+['seller_id'=>auth()->user()->role==='admin'?null:auth()->id(),'active'=>1,'created_at'=>now(),'updated_at'=>now()]));return $this->done($r,'Voucher saved.');}
 public function cancel(Request $r,int $id){$v=$r->validate(['reason'=>'required|string|min:10|max:300']);Commerce::cancel($id,$v['reason'],auth()->id());return $this->done($r,'Order cancelled.');}
 public function returnCreate(Request $r){$v=$r->validate(['order_id'=>'required|integer','reason'=>'required|in:Damaged,Wrong item,Not as described','description'=>'required|string|min:10|max:500']);$photos=Support::photos($r,'photos',1,5,'local');$result=Support::once($r,'return',function()use($v,$photos){$o=DB::table('orders')->where('id',$v['order_id'])->where('buyer_id',auth()->id())->lockForUpdate()->first();abort_unless($o,403);if($o->status!=='DELIVERED'||!$o->delivered_at||now()->gte(now()->parse($o->delivered_at)->addDays(7)))Support::fail('order','Returns are allowed within 7 days after delivery and before completion.');if(DB::table('return_requests')->where('order_id',$o->id)->exists())Support::fail('order','A return request already exists.');$id=DB::table('return_requests')->insertGetId($v+['buyer_id'=>auth()->id(),'seller_id'=>$o->seller_id,'photos'=>json_encode($photos),'created_at'=>now(),'updated_at'=>now()]);Support::notify([$o->seller_id],"Return request #{$id} received.");return $id;});return $this->done($r,'Return requested.',$result);}
 public function returnRespond(Request $r){$v=$r->validate(['id'=>'required|integer','decision'=>'required|in:approved,rejected','reason'=>'required|string|min:10|max:300']);DB::transaction(function()use($v){$x=DB::table('return_requests')->where('id',$v['id'])->where('seller_id',auth()->id())->lockForUpdate()->first();abort_unless($x,403);if($x->status!=='requested')Support::fail('return','This request has already been handled.');DB::table('return_requests')->where('id',$x->id)->update(['status'=>$v['decision'],'response'=>$v['reason'],'responded_at'=>now(),'updated_at'=>now()]);Support::notify([$x->buyer_id],"Return #{$x->id} {$v['decision']}: {$v['reason']}");});return $this->done($r,'Response saved.');}
 public function returnEscalate(Request $r){$id=$r->validate(['id'=>'required|integer'])['id'];$x=DB::table('return_requests')->where('id',$id)->where('buyer_id',auth()->id())->first();abort_unless($x,403);if($x->status!=='rejected'||$x->escalated||now()->gt(now()->parse($x->responded_at)->addDays(3)))Support::fail('return','The escalation window is closed.');DB::table('return_requests')->where('id',$id)->update(['status'=>'disputed','escalated'=>1,'updated_at'=>now()]);Support::notify(DB::table('users')->where('role','admin')->pluck('id')->all(),"Return dispute #{$id} needs review.");return $this->done($r,'Dispute opened.');}
 public function returnReceived(Request $r){$id=$r->validate(['id'=>'required|integer'])['id'];DB::transaction(function()use($id){$x=DB::table('return_requests')->where('id',$id)->where('seller_id',auth()->id())->lockForUpdate()->first();abort_unless($x,403);if($x->status==='received')return;if($x->status!=='approved')Support::fail('return','Approve the return before confirming receipt.');$o=DB::table('orders')->where('id',$x->order_id)->lockForUpdate()->first();Commerce::restore($o);Commerce::refund($o);DB::table('return_requests')->where('id',$id)->update(['status'=>'received','updated_at'=>now()]);DB::table('orders')->where('id',$o->id)->update(['status'=>'RETURN_RECEIVED','updated_at'=>now()]);DB::table('parcels')->where('order_id',$o->id)->update(['status'=>'RETURN_RECEIVED','updated_at'=>now()]);Support::notify([$x->buyer_id],"Returned order #{$o->id} received; refund pending confirmation.");});return $this->done($r,'Receipt saved.');}
 public function payout(Request $r){$v=$r->validate(['amount'=>'required|numeric|decimal:0,2|min:100','account'=>'required|string|max:190']);$id=Support::once($r,'payout',function()use($v){if(DB::table('payouts')->where('seller_id',auth()->id())->where('status','pending')->exists())Support::fail('payout','A payout is already pending.');if($v['amount']>Commerce::available(auth()->id()))Support::fail('amount','Amount exceeds your available balance.');return DB::table('payouts')->insertGetId($v+['seller_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);});return $this->done($r,'Payout requested.',$id);}
 public function review(Request $r){$v=$r->validate(['order_item_id'=>'required|integer','stars'=>'required|integer|between:1,5','comment'=>'nullable|string|max:500']);$photos=Support::photos($r);DB::transaction(function()use($v,$photos){$i=DB::table('order_items')->find($v['order_item_id']);abort_unless($i,404);$o=DB::table('orders')->where('id',$i->order_id)->where('buyer_id',auth()->id())->lockForUpdate()->first();abort_unless($o,403);if($o->status!=='COMPLETED'||!$o->completed_at||now()->gt(now()->parse($o->completed_at)->addDays(30)))Support::fail('review','Reviewing is allowed within 30 days of completion.');$old=DB::table('item_reviews')->where('order_item_id',$i->id)->first();if($old&&$old->edit_count>=1)Support::fail('review','A review can be edited only once.');$data=$v+['buyer_id'=>auth()->id(),'seller_id'=>$o->seller_id,'updated_at'=>now()];$data['photos']=json_encode($photos?:json_decode($old->photos??'[]',true));if($old)DB::table('item_reviews')->where('id',$old->id)->update($data+['edit_count'=>1]);else DB::table('item_reviews')->insert($data+['created_at'=>now()]);});return $this->done($r,'Review saved.');}
 public function reviewReply(Request $r){$v=$r->validate(['id'=>'required|integer','response'=>'required|string|max:500']);abort_unless(DB::table('item_reviews')->where('id',$v['id'])->where('seller_id',auth()->id())->update(['seller_response'=>$v['response'],'updated_at'=>now()]),404);return $this->done($r,'Reply saved.');}
 public function password(Request $r){$v=$r->validate(['current_password'=>'required','password'=>['required','confirmed',\Illuminate\Validation\Rules\Password::min(8)->mixedCase()->numbers()->symbols()]]);if(!Hash::check($v['current_password'],auth()->user()->password))Support::fail('current_password','Current password is incorrect.');DB::table('users')->where('id',auth()->id())->update(['password'=>Hash::make($v['password']),'remember_token'=>null,'api_token_expires_at'=>null,'updated_at'=>now()]);$r->session()->regenerate();return $this->done($r,'Password changed; mobile tokens revoked.');}
 public function contactRequest(Request $r){$v=$r->validate(['password'=>'required','email'=>'nullable|email','phone'=>'nullable|string']);if(!Hash::check($v['password'],auth()->user()->password))Support::fail('password','Password is incorrect.');$data=[];if(!empty($v['email'])){$email=mb_strtolower(trim($v['email']));if(DB::table('users')->where('email',$email)->where('id','!=',auth()->id())->exists())Support::fail('email','Email already used.');$data['email']=$email;}if(!empty($v['phone'])){$phone=\App\Services\Registration::normalizePhone($v['phone']);if(!preg_match('/^09[0-9]{9}$/',$phone))Support::fail('phone','Enter a valid Philippine mobile number.');if(DB::table('users')->where(fn($q)=>$q->where('phone_normalized',$phone)->orWhere('phone',$phone))->where('id','!=',auth()->id())->exists())Support::fail('phone','Mobile number already used.');$data['phone']=$phone;$data['phone_normalized']=$phone;}if(!$data)Support::fail('contact','Enter a new email or phone.');$otp=(string)random_int(100000,999999);$r->session()->put('contact_change',['data'=>$data,'hash'=>Hash::make($otp),'expires'=>now()->addMinutes(5)->timestamp,'attempts'=>0]);Mail::raw('Your account change verification code is '.$otp,fn($m)=>$m->to($data['email']??auth()->user()->email)->subject('Verify account change'));return $this->done($r,'Verification sent by email. Phone SMS verification requires an SMS provider.');}
 public function contactVerify(Request $r){$v=$r->validate(['otp'=>['required','regex:/^[0-9]{6}$/']]);$x=$r->session()->get('contact_change');if(!$x||$x['expires']<=time()||$x['attempts']>=5)Support::fail('otp','Expired or locked request.');if(!Hash::check($v['otp'],$x['hash'])){$x['attempts']++;$r->session()->put('contact_change',$x);Support::fail('otp','Incorrect OTP.');}DB::table('users')->where('id',auth()->id())->update($x['data']+['remember_token'=>null,'updated_at'=>now()]);$r->session()->forget('contact_change');return $this->done($r,'Contact updated.');}
 public function notificationsRead(Request $r){DB::table('notifications')->where('user_id',auth()->id())->whereNull('read_at')->update(['read_at'=>now()]);return $this->done($r,'Notifications marked read.');}
 public function payment(Request $r){$v=$r->validate(['payment_id'=>'required|integer','reference'=>'required|string|max:190']);DB::transaction(function()use($v){$initial=DB::table('payments')->where('id',$v['payment_id'])->first();abort_unless($initial,404);$o=DB::table('orders')->where('id',$initial->order_id)->lockForUpdate()->first();$p=DB::table('payments')->where('id',$initial->id)->lockForUpdate()->first();abort_unless($p&&$p->method==='manual',404);if($p->status==='paid')return;if($o->status==='CANCELLED'||now()->gte(now()->parse($o->created_at)->addHour()))Support::fail('payment','Order is cancelled; do not confirm a late payment.');DB::table('payments')->where('id',$p->id)->update(['status'=>'paid','reference'=>$v['reference'],'updated_at'=>now()]);Support::audit('payment-confirmed','payment',$p->id,$p,['status'=>'paid'],$v['reference']);Support::notify([$o->buyer_id,$o->seller_id],"Payment confirmed for order #{$o->id}.");});return $this->done($r,'Payment recorded.');}
 public function refund(Request $r){$v=$r->validate(['order_id'=>'required|integer','reference'=>'required|string|max:190']);DB::transaction(function()use($v){$refund=DB::table('refunds')->where('order_id',$v['order_id'])->lockForUpdate()->first();abort_unless($refund,404);if($refund->status==='paid')return;DB::table('refunds')->where('id',$refund->id)->update(['status'=>'paid','reference'=>$v['reference'],'updated_at'=>now()]);DB::table('orders')->where('id',$v['order_id'])->update(['refunded_at'=>now(),'updated_at'=>now()]);Support::audit('refund-confirmed','refund',$refund->id,$refund,['status'=>'paid'],$v['reference']);});return $this->done($r,'External refund recorded.');}
 public function payoutPaid(Request $r){$v=$r->validate(['id'=>'required|integer','reference'=>'required|string|max:190']);DB::transaction(function()use($v){$x=DB::table('payouts')->where('id',$v['id'])->lockForUpdate()->first();abort_unless($x,404);if($x->status==='paid')return;DB::table('payouts')->where('id',$x->id)->update(['status'=>'paid','updated_at'=>now()]);Support::audit('payout-paid','payout',$x->id,$x,['status'=>'paid'],$v['reference']);});return $this->done($r,'External payout recorded.');}

 public function rtsReceived(Request $r){$id=$r->validate(['parcel_id'=>'required|integer'])['parcel_id'];Workflow::move($id,'RETURN_RECEIVED',auth()->id());return $this->done($r,'Return received; stock restored once and any refund queued.');}

 public function platformVoucher(Request $r){abort_unless(auth()->user()->role==='admin',403);return $this->voucher($r);}

 public function voucherEnd(Request $r){$id=$r->validate(['id'=>'required|integer'])['id'];DB::transaction(function()use($id){$x=DB::table('vouchers')->where('id',$id)->where('seller_id',auth()->user()->role==='admin'?null:auth()->id())->lockForUpdate()->first();abort_unless($x,403);DB::table('vouchers')->where('id',$id)->update(['active'=>0,'updated_at'=>now()]);DB::table('voucher_claims')->where('voucher_id',$id)->whereNotIn('buyer_id',DB::table('order_vouchers as ov')->join('orders as o','o.id','=','ov.order_id')->where('ov.voucher_id',$id)->select('o.buyer_id'))->delete();});return $this->done($r,'Voucher ended. Existing orders keep their discount.');}
 public function disputeResolve(Request $r){abort_unless(auth()->user()->role==='admin',403);$v=$r->validate(['id'=>'required|integer','decision'=>'required|in:approved,rejected','reason'=>'required|string|min:10|max:300']);DB::transaction(function()use($v){$x=DB::table('return_requests')->where('id',$v['id'])->where('status','disputed')->lockForUpdate()->first();abort_unless($x,404);DB::table('return_requests')->where('id',$x->id)->update(['status'=>$v['decision'],'response'=>$v['reason'],'responded_at'=>now(),'updated_at'=>now()]);Support::audit('dispute-resolved','return_request',$x->id,$x,$v,$v['reason']);Support::notify([$x->buyer_id,$x->seller_id],"Return dispute #{$x->id}: {$v['decision']}.");});return $this->done($r,'Dispute resolved.');}

 public function deal(Request $r){$v=$r->validate(['type'=>'required|in:bundle,buy_x_get_y','product_ids'=>'required|array|min:1','product_ids.*'=>'integer','minimum_quantity'=>'required|integer|min:1','percent'=>'required|numeric|between:0,100','gift_product_id'=>'required_if:type,buy_x_get_y|nullable|integer','gift_quantity'=>'required|integer|min:1','starts_at'=>'required|date','ends_at'=>'required|date|after:starts_at']);$ids=array_unique(array_filter(array_map('intval',$v['product_ids'])));if(!$ids)Support::fail('product_ids','Choose at least one product.');$owned=$ids;if(!empty($v['gift_product_id']))$owned[]=$v['gift_product_id'];abort_unless(DB::table('products')->where('seller_id',auth()->id())->whereIn('id',array_unique($owned))->count()===count(array_unique($owned)),403);$v['product_ids']=json_encode(array_values($ids));Support::once($r,'bundle',fn()=>DB::table('bundle_deals')->insertGetId($v+['seller_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]));return $this->done($r,'Deal scheduled; add the eligible and gift items to the cart to receive the discount.');}
 public function buyNow(Request $r){$id=DB::transaction(function()use($r){\App\Services\Cart::add($r);$q=DB::table('cart_items')->where('buyer_id',auth()->id())->where('product_id',$r->product_id)->where('variation_id',$r->input('variation_id'));$row=$q->first();$qty=$r->integer('quantity');if($row->quantity===$qty)return $row->id;$q->decrement('quantity',$qty);return DB::table('cart_items')->insertGetId(['buyer_id'=>auth()->id(),'product_id'=>$row->product_id,'variation_id'=>$row->variation_id,'quantity'=>$qty,'created_at'=>now(),'updated_at'=>now()]);});return redirect('/cart?selected='.$id);}
}
